            LinuxProcess* lp = Current();
            uint8_t z[32]; memset(z, 0, sizeof(z));
            if (which != 0) {
                if (edx && UAccess::CopyToUser(edx, z, sizeof(z)) != 0) return -14;
                return 0;
            }
